func (a *ASRockRack) syncFile(ctx context.Context, fw *serverservice.ComponentFirmwareVersion) error {
	var err error

	dstFs, tmpFs, srcFs, err := a.initRcloneFs(ctx, fw, a.logger)
	if err != nil {
		return err
	}

	// In case the file already exists in dst, don't verify/copy it
	if exists, _ := rcloneFs.FileExists(ctx, dstFs, vendors.DstPath(fw)); exists {
		a.logExistingFirmware(fw)

		return nil
	}

	err = vendors.VerifyFile(ctx, tmpFs, srcFs, fw)
	if err != nil {
		return err
	}

	err = a.copyFile(ctx, fw, dstFs, srcFs)
	if errors.Is(err, errFirmwareExists) {
		a.logExistingFirmware(fw)

		return nil
	}

	return err
}

func (a *ASRockRack) copyFile(ctx context.Context, fw *serverservice.ComponentFirmwareVersion, dstFs, srcFs rcloneFs.Fs) error {
	if exists, _ := rcloneFs.FileExists(ctx, dstFs, vendors.DstPath(fw)); exists {
		return errFirmwareExists
	}

	err := rcloneOperations.CopyFile(ctx, dstFs, srcFs, vendors.DstPath(fw), vendors.SrcPath(fw))
	if err != nil {
		if errors.Is(err, rcloneFs.ErrorObjectNotFound) {
			return errors.Wrap(vendors.ErrCopy, err.Error()+" :"+fw.Filename)
		}

		return errors.Wrap(vendors.ErrCopy, err.Error())
	}

	return nil
}

func (a *ASRockRack) logExistingFirmware(fw *serverservice.ComponentFirmwareVersion) {
	a.logger.WithFields(
		logrus.Fields{
			"filename": fw.Filename,
		},
	).Debug("firmware already exists at dst")
}

